/**
 * Feature library (requirement.md §7.9): symbolic signature features per community, generated by
 * supabase/data/build_features.py (OpenStreetMap suggestions + operator CSV). Adding or changing a
 * community's features is a data change only: edit the CSV, rerun the script.
 */
import raw from '../../../../../supabase/data/community_features.json';

export const FEATURE_KEYS = ['ctrain-station', 'pond', 'hill', 'creek', 'big-park', 'school'] as const;
export type FeatureKey = (typeof FEATURE_KEYS)[number];
export const MAX_FEATURES = 3;

export interface CommunityFeature {
  key: FeatureKey;
  /** Public place name (e.g. "Dalhousie", "Bowness Park"), or null for the generic title. */
  name: string | null;
}

export const FEATURE_INFO: Record<FeatureKey, { title: string; emoji: string }> = {
  'ctrain-station': { title: 'CTrain station', emoji: '🚉' },
  pond: { title: 'Pond', emoji: '🦆' },
  hill: { title: 'Hill', emoji: '⛰️' },
  creek: { title: 'Creek', emoji: '🏞️' },
  'big-park': { title: 'Big park', emoji: '🌳' },
  school: { title: 'School', emoji: '🏫' },
};

const isFeatureKey = (k: unknown): k is FeatureKey => typeof k === 'string' && (FEATURE_KEYS as readonly string[]).includes(k);

/** Validates the generated file; throws listing every problem. */
export function decodeFeatures(data: unknown): Record<string, CommunityFeature[]> {
  const errors: string[] = [];
  const out: Record<string, CommunityFeature[]> = {};
  const communities = (data as { communities?: unknown })?.communities;
  if (typeof communities !== 'object' || communities === null) throw new Error('Invalid feature data: communities');
  for (const [code, list] of Object.entries(communities as Record<string, unknown>)) {
    if (!Array.isArray(list)) {
      errors.push(`${code}: not a list`);
      continue;
    }
    if (list.length > MAX_FEATURES) errors.push(`${code}: more than ${MAX_FEATURES} features`);
    const seen = new Set<string>();
    out[code] = [];
    for (const f of list as { key?: unknown; name?: unknown }[]) {
      if (!isFeatureKey(f?.key)) errors.push(`${code}: unknown feature ${String(f?.key)}`);
      else if (seen.has(f.key)) errors.push(`${code}: duplicate ${f.key}`);
      else if (f.name !== null && typeof f.name !== 'string') errors.push(`${code}: bad name for ${f.key}`);
      else {
        seen.add(f.key);
        out[code].push({ key: f.key, name: f.name });
      }
    }
  }
  if (errors.length > 0) throw new Error(`Invalid feature data: ${errors.join('; ')}`);
  return out;
}

const FEATURES = decodeFeatures(raw);

/** The community's signature features in priority order (empty for unknown codes). */
export const featuresFor = (code: string): CommunityFeature[] => FEATURES[code] ?? [];
export const allFeatureCodes = (): string[] => Object.keys(FEATURES);

/** Label text, e.g. "🚉 Dalhousie" or "⛰️ Hill". */
export const featureLabel = (f: CommunityFeature): string => `${FEATURE_INFO[f.key].emoji} ${f.name ?? FEATURE_INFO[f.key].title}`;
